const item = $input.first().json;
const payload = item.body ? item.body : item;

// Extract pure email from sender field using regex
const rawSender = payload.sender_email || payload.from || payload.sender || 'client@enterprise.com';
const senderMatch = String(rawSender).match(/<([^>]+)>/);
const cleanSender = (senderMatch ? senderMatch[1] : String(rawSender)).trim().toLowerCase();

// Extract sender name
const senderName = payload.sender_name || payload.name || (senderMatch ? rawSender.split('<')[0].replace(/["']/g, '').trim() : cleanSender.split('@')[0]);

// Clean HTML tags from body
const rawBody = payload.body || payload.text || payload.content || payload.html || '';
const cleanBody = String(rawBody).replace(/<[^>]*>?/gm, ' ').replace(/\s+/g, ' ').trim();

// Normalize subject
const rawSubject = payload.subject || 'Không có tiêu đề';
const cleanSubject = String(rawSubject).trim();

// Normalize attachments
const attachments = payload.attachments || [];
const receivedAt = new Date().toISOString();

return [{
  json: {
    ...payload,
    sender_email: cleanSender,
    sender_name: senderName,
    subject: cleanSubject,
    body: cleanBody,
    clean_body: cleanBody,
    attachments: attachments,
    received_at: receivedAt,
    raw_payload: payload
  }
}];

const item = $input.first().json;
const email = String(item.sender_email || '').toLowerCase();
const subject = String(item.subject || '').toLowerCase();

// Filter out no-reply@, mailer-daemon@, postmaster@, noreply@
const isSystemEmail = email.includes('no-reply@') || 
                      email.includes('noreply@') || 
                      email.includes('mailer-daemon@') || 
                      email.includes('postmaster@') ||
                      email.startsWith('no-reply') ||
                      email.startsWith('noreply') ||
                      email.startsWith('mailer-daemon') ||
                      email.startsWith('postmaster') ||
                      subject.includes('delivery status notification') ||
                      subject.includes('undelivered mail') ||
                      subject.includes('auto-submitted');

return [{
  json: {
    ...item,
    is_system_email: isSystemEmail,
    filter_reason: isSystemEmail ? 'Email hệ thống tự sinh / No-reply / Mailer-Daemon' : null
  }
}];

